insert into public.course_modules (id, position, title, summary, status, content_version) values
  ('m1', 1, 'Understanding money and investing', 'What investing is, how it differs from saving, and the two forces that shape every long-term plan: inflation and compounding.', 'available', '2026-10-17'),
  ('m2', 2, 'How the stock market works', 'What a share really is, how exchanges match buyers and sellers, and why prices move during the day.', 'coming_soon', '2026-10-17'),
  ('m3', 3, 'Different types of investments', 'Shares, bonds, funds, ETFs, cash and more: what each is, and which carry extra complexity or risk.', 'coming_soon', '2026-10-17'),
  ('m4', 4, 'Understanding risk', 'Volatility, diversification, concentration, currency and leverage, and how your time horizon changes all of them.', 'coming_soon', '2026-10-17'),
  ('m5', 5, 'How to evaluate a company', 'Reading the numbers behind a business, and the limits of each metric.', 'coming_soon', '2026-10-17'),
  ('m6', 6, 'ETFs and building a diversified portfolio', 'How index funds work, what you actually own, and how a portfolio fits together.', 'coming_soon', '2026-10-17'),
  ('m7', 7, 'Practical investing', 'Orders, fees, statements and UK tax wrappers, explained using Trading 212''s features.', 'coming_soon', '2026-10-17'),
  ('m8', 8, 'Developing an investment thesis', 'Researching a company, separating facts from opinions, and knowing what would prove you wrong.', 'coming_soon', '2026-10-17'),
  ('m9', 9, 'Behaviour and psychology', 'The mental traps that cost investors the most, and how to build habits that avoid them.', 'coming_soon', '2026-10-17'),
